python3 - <<'PY'
# 1. The worker must name the flows' real home before `updates/` can ever be retired.
p='packs/claudinite-lifecycle/tasks/update/worker.mjs'
s=open(p).read()
for mod in ('engine-update', 'pack-update', 'terminals'):
    a=f"await load('updates/{mod}.mjs')"; b=f"await load('packs/claudinite-lifecycle/updates/{mod}.mjs')"
    assert s.count(a)==1, mod
    s=s.replace(a,b)
open(p,'w').write(s)
print('worker repointed')

# 2. install.test.mjs pins the surface FIELDED workers call — which is both, right now.
p2='engine-tests/install.test.mjs'
t=open(p2).read()
old = """  // The paths moved with the flows (#1317). The old `updates/*` re-exports were deleted
  // once the fleet's workers had been read and none named them — which is what chain link
  // L3 confirms; a worker one cycle behind loads these from the canon tree it just fetched.
  const fielded = {
    'packs/claudinite-lifecycle/updates/terminals.mjs': ['terminalFor'],
    'packs/claudinite-lifecycle/updates/engine-update.mjs': ['engineUpdate'],
    'packs/claudinite-lifecycle/updates/pack-update.mjs': ['packUpdate'],
  };"""
new = """  // The paths moved with the flows (#1317), and BOTH are fielded right now. The worker resolves
  // these against a FRESH CANON CLONE at HEAD rather than its own mount, so the surface a member
  // calls is whatever ITS vendored worker names — and every member vendored a worker naming
  // `updates/*` on 2026-08-24. The pack paths are what the worker names from this commit on; the
  // `updates/*` re-exports stay callable until the fleet has vendored that worker, which is read
  // off the members and never off this repo's own tree.
  const fielded = {
    'updates/terminals.mjs': ['terminalFor'],
    'updates/engine-update.mjs': ['engineUpdate'],
    'updates/pack-update.mjs': ['packUpdate'],
    'packs/claudinite-lifecycle/updates/terminals.mjs': ['terminalFor'],
    'packs/claudinite-lifecycle/updates/engine-update.mjs': ['engineUpdate'],
    'packs/claudinite-lifecycle/updates/pack-update.mjs': ['packUpdate'],
  };"""
assert t.count(old)==1
open(p2,'w').write(t.replace(old,new))
print('both surfaces pinned')
PY
git add -A && node --test engine-tests/install.test.mjs packs/claudinite-tasks/test/engine-pack-lane-shims.test.mjs 2>&1 | grep -E "^(not ok|# (tests|pass|fail))"

