// The diff classifier behind the request mode's merge authorization (DESIGN
// §16.11): what counts as narrow, and what a real branch reads as.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { removeTree } from '../../../../engine/remove-tree.mjs';
import {
  classifyPath, commentOnly, narrowVerdict, diffEntries,
} from '../../queue/tasks/implement-request/narrow-diff.mjs';

test('classifyPath names docs, tests and code', () => {
  assert.equal(classifyPath('README.md'), 'doc');
  assert.equal(classifyPath('docs/tasks-dispatch/DESIGN.md'), 'doc');
  assert.equal(classifyPath('packs/claudinite-tasks/test/scheduler-run.test.mjs'), 'test');
  assert.equal(classifyPath('packs/basics/tests/fixture.json'), 'test');
  assert.equal(classifyPath('packs/basics/test/pack.test.mjs'), 'test');
  assert.equal(classifyPath('app/test_parser.py'), 'test');
  assert.equal(classifyPath('packs/claudinite-tasks/queue/scheduler-run.mjs'), 'code');
  // A whole-segment match, so a directory that merely CONTAINS the word is code.
  assert.equal(classifyPath('src/latest/index.mjs'), 'code');
});

test('commentOnly sees through comments, and only in languages it models', () => {
  const before = 'export const a = 1; // one\n\n/* block */\nexport const b = 2;\n';
  const after = '// a different comment\nexport const a = 1;\nexport const b = 2;\n';
  assert.equal(commentOnly('engine/x.mjs', before, after), true);
  assert.equal(commentOnly('engine/x.mjs', before, after.replace('= 2', '= 3')), false);
  // A `#`-comment language is not modeled: its comment-only change reads as code,
  // which is the safe end of the verdict.
  assert.equal(commentOnly('scripts/x.py', 'a = 1  # one\n', 'a = 1  # two\n'), false);
  // An added file has no "before" to compare against.
  assert.equal(commentOnly('engine/x.mjs', null, after), false);
});

test('narrowVerdict: docs, tests, comments and one code directory are narrow', () => {
  const v = narrowVerdict([
    { file: 'README.md', before: 'a', after: 'b' },
    { file: 'engine-tests/queue/scheduler-run.test.mjs', before: 'a', after: 'b' },
    { file: 'packs/claudinite-tasks/scheduler-run.mjs', before: 'const a = 1;\n', after: 'const a = 2;\n' },
    { file: 'packs/claudinite-tasks/queue/read.mjs', before: 'const a = 1; // x\n', after: 'const a = 1; // y\n' },
  ]);
  assert.equal(v.narrow, true);
  assert.deepEqual(v.codeDirs, ['packs/claudinite-tasks']);
});

test('narrowVerdict: code in two directories is not narrow, and says which', () => {
  const v = narrowVerdict([
    { file: 'engine/a.mjs', before: 'const a = 1;\n', after: 'const a = 2;\n' },
    { file: 'packs/basics/b.mjs', before: 'const b = 1;\n', after: 'const b = 2;\n' },
  ]);
  assert.equal(v.narrow, false);
  assert.deepEqual(v.codeDirs, ['engine', 'packs/basics']);
  assert.match(v.why, /2 directories/);
});

test('narrowVerdict: a diff with no code at all is narrow', () => {
  const v = narrowVerdict([{ file: 'docs/DESIGN.md', before: 'a', after: 'b' }]);
  assert.equal(v.narrow, true);
  assert.deepEqual(v.codeDirs, []);
});

test('diffEntries reads a real branch, added and deleted files included', () => {
  const repo = mkdtempSync(path.join(tmpdir(), 'narrow-diff-'));
  const git = (...args) => execFileSync('git', args, { cwd: repo, encoding: 'utf8' });
  try {
    git('init', '-q', '-b', 'main');
    git('config', 'user.email', 'test@example.com');
    git('config', 'user.name', 'test');
    mkdirSync(path.join(repo, 'engine'));
    writeFileSync(path.join(repo, 'engine/a.mjs'), 'const a = 1; // one\n');
    writeFileSync(path.join(repo, 'engine/gone.mjs'), 'const g = 1;\n');
    git('add', '-A');
    git('commit', '-qm', 'base');

    git('checkout', '-q', '-b', 'work');
    writeFileSync(path.join(repo, 'engine/a.mjs'), 'const a = 1; // two\n');
    writeFileSync(path.join(repo, 'README.md'), 'hello\n');
    rmSync(path.join(repo, 'engine/gone.mjs'));
    git('add', '-A');
    git('commit', '-qm', 'work');

    const entries = diffEntries({ base: 'main', cwd: repo });
    assert.deepEqual(entries.map((e) => e.file).sort(), ['README.md', 'engine/a.mjs', 'engine/gone.mjs']);
    const added = entries.find((e) => e.file === 'README.md');
    assert.equal(added.before, null);
    const deleted = entries.find((e) => e.file === 'engine/gone.mjs');
    assert.equal(deleted.after, null);

    const v = narrowVerdict(entries);
    // The comment-only edit drops out; the DELETED module is a code change in its
    // directory, and it is the only one, so the diff is still narrow.
    assert.equal(v.narrow, true);
    assert.deepEqual(v.codeDirs, ['engine']);
  } finally {
    removeTree(repo);
  }
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fileURLToPath } from 'node:url';
import { makeRepo, cleanup } from '../../../engine-tests/helpers.mjs';
import { buildContext } from '../../../engine/checks/helpers/repo-context.mjs';
import { loadDeclaredChecks } from '../../../engine/checks/helpers/pattern-rules.mjs';

const rule = loadDeclaredChecks(fileURLToPath(new URL('../../../packs/claudinite-lifecycle', import.meta.url)))
  .find((r) => r.id === 'scheduler-workflow-shape');

const WF = '.github/workflows/claudinite-scheduler.yml';
const goodWorkflow = `name: Claudinite scheduler
on:
  schedule:
    - cron: '25 4,16 * * *'
  workflow_dispatch:
concurrency:
  group: claudinite-scheduler
permissions:
  contents: write
  issues: write
  pull-requests: write
  actions: read
jobs:
  schedule:
    runs-on: ubuntu-latest
    steps:
      - run: node .claudinite/shared/packs/claudinite-tasks/queue/scheduler-run.mjs
`;

const run = (files) => {
  const root = makeRepo({ changed: files });
  try { return rule.run(buildContext({ root, mode: 'all' })); } finally { cleanup(root); }
};

test('scheduler-workflow-shape: a conforming workflow yields no findings', () => {
  assert.deepEqual(run({ [WF]: goodWorkflow }), []);
});

test('scheduler-workflow-shape: is inert when the scheduler workflow is absent', () => {
  assert.deepEqual(run({ '.github/workflows/ci.yml': 'name: CI\non: push\n' }), []);
});

test('scheduler-workflow-shape: flags an off-band cron minute', () => {
  const f = run({ [WF]: goodWorkflow.replace("'25 4,16 * * *'", "'5 4,16 * * *'") });
  assert.equal(f.length, 1);
  assert.match(f[0].what, /cron: '5 4,16 \* \* \*' is not two daily ticks/);
});

// The two-tick form (DESIGN §17) is what the converge writes now; a single daily hour is neither
// that nor the legacy hourly line, so it is still a drifted cron.
test('scheduler-workflow-shape: accepts two daily ticks, and flags a single daily hour', () => {
  assert.deepEqual(run({ [WF]: goodWorkflow.replace("'25 4,16 * * *'", "'25 4,16 * * *'") }), []);
  assert.deepEqual(run({ [WF]: goodWorkflow.replace("'25 4,16 * * *'", "'25 0,12 * * *'") }), []);
  assert.deepEqual(run({ [WF]: goodWorkflow.replace("'25 4,16 * * *'", "'25 23,11 * * *'") }), []);

  const f = run({ [WF]: goodWorkflow.replace("'25 4,16 * * *'", "'25 4 * * *'") });
  assert.equal(f.length, 1);
  assert.match(f[0].what, /cron: '25 4 \* \* \*' is not two daily ticks/);
});

// THE HOURLY LINE IS RETIRED (#1234). It was accepted only because `.github/workflows/` is the one
// path a converge cannot push, so each member held its hourly cron until its own apply-stage pull
// request landed — and going red in that window would have fired the check on every member the
// change had not reached. All 13 now carry the two-tick form, so the tolerance is gone and the
// line it covered is a drifted cron like any other.
test('scheduler-workflow-shape: the retired hourly cron is now flagged', () => {
  const f = run({ [WF]: goodWorkflow.replace("'25 4,16 * * *'", "'25 * * * *'") });
  assert.equal(f.length, 1);
  assert.match(f[0].what, /cron: '25 \* \* \* \*' is not two daily ticks/);
});

test('scheduler-workflow-shape: flags a second cron schedule', () => {
  const two = goodWorkflow.replace("    - cron: '25 4,16 * * *'\n",
    "    - cron: '25 4,16 * * *'\n    - cron: '40 4,16 * * *'\n");
  const f = run({ [WF]: two });
  assert.equal(f.length, 1);
  assert.match(f[0].what, /declares 2 cron schedules, expected exactly one/);
});

test('scheduler-workflow-shape: flags a workflow with no cron at all', () => {
  const none = goodWorkflow.replace("  schedule:\n    - cron: '25 4,16 * * *'\n", '');
  const whats = run({ [WF]: none }).map((x) => x.what).join(' | ');
  assert.match(whats, /declares 0 cron schedules, expected exactly one/);
});

test('scheduler-workflow-shape: flags a read-only scheduler (baselining deliver() needs write)', () => {
  const readOnly = goodWorkflow
    .replace('contents: write', 'contents: read')
    .replace('  pull-requests: write\n', '');
  const whats = run({ [WF]: readOnly }).map((x) => x.what).join(' | ');
  assert.match(whats, /does not grant contents: write/);
  assert.match(whats, /does not grant pull-requests: write/);
});

test('scheduler-workflow-shape: flags missing concurrency, dispatch, and engine entry', () => {
  const stripped = `name: Claudinite scheduler
on:
  schedule:
    - cron: '25 * * * *'
jobs:
  schedule:
    steps:
      - run: echo hi
`;
  const whats = run({ [WF]: stripped }).map((x) => x.what).join(' | ');
  assert.match(whats, /no workflow_dispatch/);
  assert.match(whats, /no concurrency group/);
  assert.match(whats, /does not run the vendored scheduler entry/);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

// The engine lane and the pack lane deliver in SEPARATE PRs on separate cycles, and
// pack delivery is version-gated per pack — so every member spends a window holding
// the new engine beside an old pack. A `packs/**` file importing an `engine/**`
// module is therefore a stale caller of an instantly-current engine, and an engine
// module it names may not simply vanish.
//
// It vanished once (#1004). `packs/claudinite-lifecycle/task-declaration-shape.mjs` imported
// the engine's own `slots.mjs`, #974 renamed that to `calendar.mjs`, and the next
// member to converge got a mount whose `core` pack would not load — which fails the
// self-test, which makes the converge refuse to land AT ALL, so the member could not
// even receive the pack version that would have fixed it.
//
// QUANTIFIED OVER HISTORY, NOT A LIST. Which symbols matter is a fact about the pack
// versions members are actually carrying, and members carry old ones — so the
// question is asked of every version of every pack file that ever REACHED the trunk,
// not of HEAD and not of a list someone remembers to update.
//
// The trunk, not `--all`: a member's pack version came from a release cut from the
// default branch, so an import that only ever existed on an unmerged branch is not a
// fielded import. Scanning every ref instead fires on whatever else is in flight —
// which is exactly what it did the first time this test ran.

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const git = (...args) => execFileSync('git', args, { cwd: ROOT, encoding: 'utf8', maxBuffer: 64e6 });
const gitOk = (...args) => { try { git(...args); return true; } catch { return false; } };

// The trunk as this checkout can name it. CI checks out the PR head with full
// history and `origin/main` present; a local branch has it too. `HEAD` is the
// fallback rather than a hard failure, since a checkout without the remote ref is a
// worse-scoped run, not a broken one.
const TRUNK = gitOk('rev-parse', '--verify', 'origin/main') ? 'origin/main' : 'HEAD';

// Every `import { … } from '…/engine/<path>'` that any version of any packs/** file
// has ever carried, as `{ enginePath -> Set<symbol> }`.
function fieldedEngineImports() {
  // One log walk over the pack tree, with each commit's blobs; `-p` gives the diffs
  // and the added lines are what a member could have installed.
  const text = git('log', TRUNK, '--format=%H', '-p', '--unified=0', '--', 'packs/');
  const out = new Map();
  const RE = /^\+\s*import\s*\{([^}]*)\}\s*from\s*'[^']*?engine\/([^']+)'/;
  // A pack's tests live inside the pack and are dropped from every vendor set, so no
  // member ever holds one — their imports are not fielded, and counting them would
  // pin an engine symbol alive on the strength of a file nobody installs. The `+++`
  // header names the file each run of added lines belongs to.
  let file = '';
  for (const line of text.split('\n')) {
    if (line.startsWith('+++ ')) { file = line.slice(4).replace(/^b\//, ''); continue; }
    if (file.endsWith('.test.mjs')) continue;
    const m = RE.exec(line);
    if (!m) continue;
    const path = `engine/${m[2].replace(/^(\.\.\/)+/, '')}`;
    const syms = m[1].split(',').map((s) => s.trim().split(/\s+as\s+/)[0].trim()).filter(Boolean);
    if (!out.has(path)) out.set(path, new Set());
    for (const s of syms) out.get(path).add(s);
  }
  return out;
}

// A RETIRED PATH is one whose fielded callers were READ AND FOUND GONE — not one whose
// deletion was convenient. `engine/scheduler/*` moved to the tasks pack in #1317 and its
// shims came out at chain link L4, after L3 observed every member's stamp carrying the
// pack and a full queue cycle running from the new paths. Nothing goes in this list on
// the strength of "the current tree does not import it": the whole point of the scan is
// that the current tree is not what members are carrying.
const RETIRED = [/^engine\/scheduler\//];

test('every engine module a fielded pack version imports still resolves, with the symbols it named', async () => {
  // A SHALLOW checkout has no history to walk, so the scan would find nothing and
  // report clean — a green run that proved nothing. Say so instead: CI checks out
  // with `fetch-depth: 0` precisely so scans like this one can work.
  assert.ok(gitOk('rev-parse', `${TRUNK}~50`),
    `this checkout is too shallow to walk ${TRUNK}'s pack history — fetch with depth 0 before trusting this test`);

  const imports = fieldedEngineImports();
  assert.ok(imports.size > 0, 'the history walk found no pack->engine imports at all — the scan is broken, not the tree');

  const missing = [];
  for (const [path, symbols] of imports) {
    if (RETIRED.some((r) => r.test(path))) continue;
    let mod;
    try {
      mod = await import(join(ROOT, path));
    } catch (e) {
      missing.push(`${path} — cannot be imported at all (${e.code ?? e.message}); a pack that fails to load fails the mount's self-test`);
      continue;
    }
    for (const s of symbols) {
      if (!(s in mod)) missing.push(`${path} no longer exports \`${s}\``);
    }
  }
  assert.deepEqual(missing, [], `a fielded pack version imports these and would break mid-converge:\n  ${missing.join('\n  ')}`);
});

test('the shims re-export rather than re-declare, so they cannot drift from the real home', async () => {
  const [slots, calendar, run, github] = await Promise.all([
    import(join(ROOT, 'packs/claudinite-tasks/slots.mjs')),
    import(join(ROOT, 'packs/claudinite-tasks/calendar.mjs')),
    import(join(ROOT, 'packs/claudinite-tasks/run.mjs')),
    import(join(ROOT, 'packs/claudinite-tasks/github.mjs')),
  ]);
  assert.equal(slots.FREQUENCIES, calendar.FREQUENCIES, 'same object, not a copy');
  assert.equal(run.ensureLabels, github.ensureLabels, 'same function, not a copy');
});

test('the one duplicated body agrees with the pack that owns it now', async () => {
  // `parseOverrides` cannot re-export: its home is claudinite-fleet-sheepdog's param-bag.mjs, and the
  // engine may not import a pack. So it is duplicated, and this is the drift guard —
  // run against the real logic in both directions, not a string compare.
  const { parseOverrides } = await import(join(ROOT, 'packs/claudinite-tasks/run.mjs'));
  const { parseParamBag } = await import(join(ROOT, 'packs/claudinite-fleet-sheepdog/param-bag.mjs'));
  for (const raw of [
    'DIGEST_BACKFILL_DAYS=7',
    'A=1,B=2',
    'REPOS=Alpha Beta\nDRY_RUN=true',
    'INCLUDE_DORMANT',
    '',
  ]) {
    assert.deepEqual(parseOverrides(raw), parseParamBag(raw), `disagreed on ${JSON.stringify(raw)}`);
  }
  // Where they legitimately differ, say so rather than pretend: the pack's parser
  // ignores non-SHOUTING tokens because a work item's Context is prose first. The
  // shim keeps the old permissive shape, because a fielded worker feeds it the old
  // channel, which never carried prose.
  assert.deepEqual(parseParamBag('some prose here'), {});
  assert.deepEqual(parseOverrides('some prose here'), { 'some prose here': 'true' });
});

