// Converge ONE member from this canon checkout: declare claudinite-tasks if absent,
// vendor the current canon into its mount, and regenerate its two workflow files
// from the pack's own stubs. argv: <member-root> <owner/repo>. Prints what changed.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const [root, fullName] = process.argv.slice(2);
if (!root || !fullName) { console.error('usage: converge-member.mjs <member-root> <owner/repo>'); process.exit(1); }
const CANON = '/home/user/Claudinite';

// 1. Declare the pack if the member does not already. Seed only — never touch an
//    existing entry, which carries that member's own config and answers.
const settingsFile = join(root, '.claudinite-settings.json');
const raw = JSON.parse(readFileSync(settingsFile, 'utf8'));
const has = (raw.packs ?? []).some((p) => typeof p === 'object' && p.id === 'claudinite-tasks');
if (!has) {
  raw.packs.push({ id: 'claudinite-tasks' });
  writeFileSync(settingsFile, `${JSON.stringify(raw, null, 2)}\n`);
  console.log('declared: claudinite-tasks');
} else {
  console.log('declared: already present');
}

// 2. Vendor the current canon into the mount, which also stamps the versions.
const { applyVendor } = await import(`${CANON}/vendoring/apply-vendor-set.mjs`);
const res = await applyVendor(root);
if (res.errors?.length) { for (const e of res.errors) console.error(`ERROR: ${e.what}\n  fix: ${e.fix}`); process.exit(1); }
console.log(`vendored: ${res.files} files`);

// 3. Regenerate both workflow files from the stubs now in the member's own mount,
//    so their `run:` lines name the pack paths rather than the retiring engine ones.
const { convergeWorkflows, declaredSecrets, stubsDir } = await import(`${CANON}/packs/claudinite-tasks/converge-workflows.mjs`);
const { loadConfig } = await import(`${CANON}/engine/checks/helpers/repo-context.mjs`);
const config = loadConfig(root);
const stubs = stubsDir(root);
const schedulerStub = join(stubs, 'claudinite-scheduler.yml');
const executorStub = join(stubs, 'claudinite-executor.yml');
if (!existsSync(schedulerStub)) { console.error(`no stub at ${schedulerStub}`); process.exit(1); }
const { changed } = convergeWorkflows(root, fullName, {
  schedulerStub: readFileSync(schedulerStub, 'utf8'),
  executorStub: existsSync(executorStub) ? readFileSync(executorStub, 'utf8') : null,
  secretNames: await declaredSecrets(root, config),
  dailyHour: config?.taskScheduler?.dailyHour,
});
console.log(`workflows: ${changed.length ? changed.join(', ') : 'already converged'}`);
